// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IRewardRouterV2, IGlpManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public {
        c = new DnGmxBatchingManager();
        c.initialize(
            IERC20(address(1)),
            IERC20(address(2)),
            IRewardRouterV2(address(3)),
            IGlpManager(address(this)),
            address(4),
            address(5)
        );
    }

    function vault() external view returns (address) {
        return address(1);
    }

    function testFuzz_property(address newOwner) public {
        // setUp made this contract the owner, so transferOwnership is callable here.
        // General rule: ownership transfer completes if and only if the candidate
        // owner is NOT the zero address. The mutant inverts the guard, so it
        // accepts the zero address and rejects every nonzero candidate.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok != (newOwner == address(0)), "transfer must succeed iff newOwner is nonzero");
    }
}
